/// <summary>
/// AVA <c>initializeSalesQuotationHeaderTmp</c>
/// </summary>
/// <param name = "_custQuotationConfirmJour">CustQuotationConfirmJour</param>
/// <param name = "_formLetterRemarks">FormLetterRemarks</param>
/// <param name = "_custFormletterDocument">CustFormletterDocument</param>
/// <param name = "_custFormletterParameters">CustFormletterParameters</param>
/// <returns>SalesQuotationHeaderTmp</returns>
protected SalesQuotationHeaderTmp initializeSalesQuotationHeaderTmp(
    CustQuotationConfirmJour    _custQuotationConfirmJour,
    FormLetterRemarks           _formLetterRemarks,
    CustFormletterDocument      _custFormletterDocument,
    CustFormletterParameters    _custFormletterParameters)
{
    SalesQuotationHeaderTmp avaSalesQuotationHeaderTmp = next initializeSalesQuotationHeaderTmp(_custQuotationConfirmJour, _formLetterRemarks, _custFormletterDocument, _custFormletterParameters);

    FormLetterRemarks avaFormLetterRemarks1 = FormLetterRemarks::find(_custQuotationConfirmJour.LanguageId, FormTextType::AVASalesQuotation_Header1);
    FormLetterRemarks avaFormLetterRemarks2 = FormLetterRemarks::find(_custQuotationConfirmJour.LanguageId, FormTextType::AVASalesQuotation_Header2);

    avaSalesQuotationHeaderTmp.AVAFormLetterRemarks_Header1 = avaFormLetterRemarks1.Txt;
    avaSalesQuotationHeaderTmp.AVAFormLetterRemarks_Header2 = avaFormLetterRemarks2.Txt;

    return avaSalesQuotationHeaderTmp;
}
